<?php include "config.php"; header('Content-Type:text/csv'); header('Content-Disposition: attachment; filename=printers.csv'); $o=fopen('php://output','w'); fputcsv($o,['inventory_id','brand','model','serial_number','ip_address','location','observations']); $r=$conn->query('SELECT * FROM printers'); while($x=$r->fetch_assoc()){ fputcsv($o,[$x['inventory_id'],$x['brand'],$x['model'],$x['serial_number'],$x['ip_address'],$x['location'],$x['observations']]); } fclose($o); ?>